// Split the reminders array into individual items for per-item processing.
// upcoming-reminders returns { success, data: [...], count: N }.
const result = $input.first().json;
const reminders = Array.isArray(result.data) ? result.data : [];
if (!reminders.length) return [];
return reminders.map(r => ({ json: r }));

// Format reminder email for each customer
const item = $input.first().json;

const dueDate = item.due_date ? new Date(item.due_date + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : 'soon';
const amount  = parseFloat(item.monthly_amount_due || item.amount_due || 0).toFixed(2);
const freq    = (item.frequency || 'recurring').charAt(0).toUpperCase() + (item.frequency || 'recurring').slice(1);
const room    = item.room_name    || 'your room';
const ref     = item.series_reference || '';
const times   = item.start_time && item.end_time ? `${item.start_time} – ${item.end_time}` : '';

const termLabel = item.payment_timing === 'in_arrears'
  ? 'This payment covers your recently completed sessions.'
  : item.payment_timing === 'per_session'
  ? 'This payment is due on the date of your next session.'
  : 'This payment covers your upcoming sessions in advance.';

const subject = `Payment Reminder: £${amount} due ${dueDate} — ${room}`;

const htmlBody = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#1e293b">
  <h2 style="color:#6366f1;border-bottom:2px solid #6366f1;padding-bottom:10px">Payment Reminder</h2>
  <p>Dear <strong>${item.customer_name || 'Valued Customer'}</strong>,</p>
  <p>This is a friendly reminder that a payment is due for your recurring booking at <strong>${room}</strong>.</p>
  <table style="width:100%;border-collapse:collapse;margin:20px 0;background:#f8fafc;border-radius:8px">
    <tr><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0"><strong>Amount Due</strong></td><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0;color:#10b981;font-size:1.1em"><strong>£${amount}</strong></td></tr>
    <tr><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0"><strong>Due Date</strong></td><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0">${dueDate}</td></tr>
    <tr><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0"><strong>Room</strong></td><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0">${room}</td></tr>
    ${times ? `<tr><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0"><strong>Session Time</strong></td><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0">${times}</td></tr>` : ''}
    <tr><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0"><strong>Frequency</strong></td><td style="padding:10px 14px;border-bottom:1px solid #e2e8f0">${freq}</td></tr>
    ${ref ? `<tr><td style="padding:10px 14px"><strong>Reference</strong></td><td style="padding:10px 14px">${ref}</td></tr>` : ''}
  </table>
  <p style="color:#64748b;font-size:0.9em">${termLabel}</p>
  <p>Please contact us if you have any questions about your payment.</p>
  <p style="margin-top:30px;color:#94a3b8;font-size:0.8em">VenueDesk — Automated Payment Reminder</p>
</div>`;

return [{ json: {
  ...item,
  email_subject: subject,
  email_html: htmlBody,
  email_to: item.customer_email
} }];
